//! Exact feature-record capture, derived from registry member declarations.
use crate::{
	model::{Registry, TypeKind},
	names, protect,
};
use anyhow::{Result, ensure};
use std::fmt::Write;

pub fn emit_features(reg: &Registry) -> Result<String> {
	let mut out = String::from(
		"// @generated by vk-gen — exact feature-record capture.\nuse crate::{core::{self as vk, StructureType}, load::{CallError, feature::Features}};\n\n",
	);
	let core = reg
		.types
		.iter()
		.find(|ty| ty.c_name == "VkPhysicalDeviceFeatures")
		.ok_or_else(|| anyhow::anyhow!("missing base physical-device features"))?;
	let TypeKind::Struct { members, .. } = &core.kind else {
		anyhow::bail!("base features must be a struct")
	};
	out.push_str("pub(super) fn capture_base(value: &vk::PhysicalDeviceFeatures, features: &mut Features) -> Result<(), CallError> {\nfeatures.record(StructureType::PHYSICAL_DEVICE_FEATURES_2, &[\n");
	for member in members {
		ensure!(
			member.ty.name == "VkBool32"
				&& member.ty.pointers.is_empty()
				&& member.ty.arrays.is_empty()
				&& member.bitfield.is_none(),
			"non-boolean base feature {}",
			member.name
		);
		writeln!(
			out,
			"({:?}, value.{}),",
			member.name,
			names::member_name(&member.name)
		)?;
	}
	out.push_str("])\n}\n\n/// Caller guarantees node points to the complete record identified by its sType.\npub(super) unsafe fn capture_node(node: *const vk::BaseInStructure, features: &mut Features) -> Result<bool, CallError> {\n// SAFETY: caller guarantees the readable chain header and complete identified record.\nmatch unsafe { (*node).s_type } {\n");
	for ty in &reg.types {
		if ty.alias_of.is_some() {
			continue;
		}
		let TypeKind::Struct {
			members, extends, ..
		} = &ty.kind
		else {
			continue;
		};
		let base = ty.c_name == "VkPhysicalDeviceFeatures2";
		if !base
			&& !extends
				.iter()
				.any(|name| name == "VkPhysicalDeviceFeatures2")
		{
			continue;
		}
		ensure!(
			base || extends.iter().any(|name| name == "VkDeviceCreateInfo"),
			"feature record cannot enable device features: {}",
			ty.c_name
		);
		ensure!(
			members.first().is_some_and(|m| m.name == "sType"
				&& m.ty.name == "VkStructureType"
				&& m.ty.pointers.is_empty()
				&& m.ty.arrays.is_empty()
				&& m.bitfield.is_none())
				&& members.get(1).is_some_and(|m| m.name == "pNext"
					&& m.ty.name == "void"
					&& m.ty.pointers.len() == 1
					&& m.ty.arrays.is_empty()
					&& m.bitfield.is_none()),
			"unsupported feature chain header: {}",
			ty.c_name
		);
		let stype = members
			.iter()
			.find(|member| member.name == "sType")
			.and_then(|member| member.values.as_deref())
			.ok_or_else(|| anyhow::anyhow!("feature record missing sType: {}", ty.c_name))?;
		let stype = stype
			.strip_prefix("VK_STRUCTURE_TYPE_")
			.ok_or_else(|| anyhow::anyhow!("invalid feature sType"))?;
		writeln!(
			out,
			"{}StructureType::{stype} => {{\n// SAFETY: the caller supplies a valid complete record for this exact sType.\nlet value = unsafe {{ &*node.cast::<vk::{}>() }};",
			protect::cfg(&ty.guards),
			names::type_name(&ty.c_name)
		)?;
		if base {
			ensure!(
				members.len() == 3
					&& members[2].name == "features"
					&& members[2].ty.name == "VkPhysicalDeviceFeatures"
					&& members[2].ty.pointers.is_empty()
					&& members[2].ty.arrays.is_empty(),
				"unsupported Features2 payload"
			);
			out.push_str("capture_base(&value.features, features)?;\n");
		} else {
			writeln!(out, "features.record(StructureType::{stype}, &[")?;
			for member in members
				.iter()
				.filter(|m| m.name != "sType" && m.name != "pNext")
			{
				ensure!(
					member.ty.name == "VkBool32"
						&& member.ty.pointers.is_empty()
						&& member.ty.arrays.is_empty()
						&& member.bitfield.is_none(),
					"unsupported feature member {}::{}",
					ty.c_name,
					member.name
				);
				writeln!(
					out,
					"({:?}, value.{}),",
					member.name,
					names::member_name(&member.name)
				)?;
			}
			out.push_str("])?;\n");
		}
		out.push_str("Ok(true)\n}\n");
	}
	out.push_str("_ => Ok(false),\n}\n}\n");
	Ok(out)
}

